questions.reponse_attendue:
def hauteur_max(t):
    h = 0
    m = 0
    for x in t:
        if x == 0:
            h = h - 1
        else:
            h = h + 1
            if h > m:
                m = h
    return m

assert hauteur_max([4, 7, 0, 2, 5, 0, 0, 9]) == 3

